1	import { useState, useCallback } from "react";
2	import { GripVertical } from "lucide-react";
3	
4	// ─── Types ───────────────────────────────────────────────────────────────────
5	
6	export interface KanbanCandidate {
7	  id: string;
8	  name: string;
9	  score: number;
10	  stage: string;
11	  email?: string | null;
12	}
13	
14	interface KanbanCardProps {
15	  candidate: KanbanCandidate;
16	  onDragStart: (e: React.DragEvent, candidateId: string) => void;
17	}
18	
19	interface KanbanColumnProps {
20	  stage: string;
21	  candidates: KanbanCandidate[];
22	  onDragStart: (e: React.DragEvent, candidateId: string) => void;
23	  onDragOver: (e: React.DragEvent, stage: string) => void;
24	  onDragLeave: () => void;
25	  onDrop: (e: React.DragEvent, stage: string) => void;
26	  isDragOver: boolean;
27	}
28	
29	interface KanbanBoardProps {
30	  jobId: string;
31	  candidates: KanbanCandidate[];
32	  onStageChange: (candidateId: string, newStage: string) => void;
33	  stages: string[];
34	}
35	
36	// ─── Stage Styling ───────────────────────────────────────────────────────────
37	
38	const STAGE_CONFIG: Record<
39	  string,
40	  { label: string; header: string; card: string; badge: string }
41	> = {
42	  applied: {
43	    label: "Applied",
44	    header:
45	      "bg-slate-100 text-slate-700 dark:bg-slate-800/60 dark:text-slate-300",
46	    card: "border-slate-200 dark:border-slate-700",
47	    badge:
48	      "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400",
49	  },
50	  screened: {
51	    label: "Screened",
52	    header:
53	      "bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300",
54	    card: "border-blue-200 dark:border-blue-800",
55	    badge:
56	      "bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400",
57	  },
58	  interview: {
59	    label: "Interview",
60	    header:
61	      "bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300",
62	    card: "border-violet-200 dark:border-violet-800",
63	    badge:
64	      "bg-violet-100 text-violet-600 dark:bg-violet-900/30 dark:text-violet-400",
65	  },
66	  offer: {
67	    label: "Offer",
68	    header:
69	      "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300",
70	    card: "border-amber-200 dark:border-amber-800",
71	    badge:
72	      "bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400",
73	  },
74	  hired: {
75	    label: "Hired",
76	    header:
77	      "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300",
78	    card: "border-emerald-200 dark:border-emerald-800",
79	    badge:
80	      "bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400",
81	  },
82	  rejected: {
83	    label: "Rejected",
84	    header:
85	      "bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300",
86	    card: "border-red-200 dark:border-red-800",
87	    badge:
88	      "bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400",
89	  },
90	};
91	
92	function getStageConfig(stage: string) {
93	  return (
94	    STAGE_CONFIG[stage] ?? {
95	      label: stage.charAt(0).toUpperCase() + stage.slice(1),
96	      header: "bg-muted text-muted-foreground",
97	      card: "border-border",
98	      badge: "bg-muted text-muted-foreground",
99	    }
100	  );
101	}
102	
103	function getScoreColor(score: number): string {
104	  if (score >= 80) return "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400";
105	  if (score >= 60) return "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400";
106	  return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400";
107	}
108	
109	// ─── KanbanCard ──────────────────────────────────────────────────────────────
110	
111	function KanbanCard({ candidate, onDragStart }: KanbanCardProps) {
112	  const scoreColor = getScoreColor(candidate.score);
113	
114	  return (
115	    <div
116	      draggable
117	      onDragStart={(e) => onDragStart(e, candidate.id)}
118	      className="group bg-card border border-border rounded-md px-3 py-2.5 cursor-grab active:cursor-grabbing shadow-sm hover:shadow-md transition-shadow duration-150 select-none"
119	    >
120	      <div className="flex items-start gap-2">
121	        <GripVertical className="h-4 w-4 text-muted-foreground/40 group-hover:text-muted-foreground/70 shrink-0 mt-0.5 transition-colors" />
122	        <div className="flex-1 min-w-0">
123	          <p className="text-sm font-semibold text-foreground truncate leading-tight">
124	            {candidate.name}
125	          </p>
126	          {candidate.email && (
127	            <p className="text-[11px] text-muted-foreground truncate mt-0.5">
128	              {candidate.email}
129	            </p>
130	          )}
131	        </div>
132	        {candidate.score > 0 && (
133	          <span
134	            className={`shrink-0 text-[11px] font-semibold px-1.5 py-0.5 rounded ${scoreColor}`}
135	          >
136	            {Math.round(candidate.score)}%
137	          </span>
138	        )}
139	      </div>
140	    </div>
141	  );
142	}
143	
144	// ─── KanbanColumn ─────────────────────────────────────────────────────────────
145	
146	function KanbanColumn({
147	  stage,
148	  candidates,
149	  onDragStart,
150	  onDragOver,
151	  onDragLeave,
152	  onDrop,
153	  isDragOver,
154	}: KanbanColumnProps) {
155	  const config = getStageConfig(stage);
156	
157	  return (
158	    <div className="flex flex-col min-w-[220px] w-[220px] shrink-0">
159	      {/* Column header */}
160	      <div
161	        className={`flex items-center justify-between px-3 py-2 rounded-t-lg ${config.header}`}
162	      >
163	        <span className="text-xs font-semibold uppercase tracking-wide">
164	          {config.label}
165	        </span>
166	        <span
167	          className={`text-[11px] font-semibold px-1.5 py-0.5 rounded-full ${config.badge}`}
168	        >
169	          {candidates.length}
170	        </span>
171	      </div>
172	
173	      {/* Drop zone */}
174	      <div
175	        className={`flex-1 min-h-[120px] rounded-b-lg border border-t-0 transition-all duration-150 ${config.card} ${
176	          isDragOver
177	            ? "border-dashed border-2 bg-primary/5 scale-[1.01]"
178	            : "bg-muted/20"
179	        }`}
180	        onDragOver={(e) => onDragOver(e, stage)}
181	        onDragLeave={onDragLeave}
182	        onDrop={(e) => onDrop(e, stage)}
183	      >
184	        <div className="p-2 space-y-2">
185	          {candidates.length === 0 ? (
186	            <p className="text-[11px] text-muted-foreground text-center py-4 italic">
187	              No candidates
188	            </p>
189	          ) : (
190	            candidates.map((candidate) => (
191	              <KanbanCard
192	                key={candidate.id}
193	                candidate={candidate}
194	                onDragStart={onDragStart}
195	              />
196	            ))
197	          )}
198	        </div>
199	      </div>
200	    </div>
201	  );
202	}
203	
204	// ─── KanbanBoard ─────────────────────────────────────────────────────────────
205	
206	export default function KanbanBoard({
207	  candidates,
208	  onStageChange,
209	  stages,
210	}: KanbanBoardProps) {
211	  const [dragOverColumn, setDragOverColumn] = useState<string | null>(null);
212	  const [draggingId, setDraggingId] = useState<string | null>(null);
213	
214	  const handleDragStart = useCallback(
215	    (e: React.DragEvent, candidateId: string) => {
216	      setDraggingId(candidateId);
217	      e.dataTransfer.effectAllowed = "move";
218	      e.dataTransfer.setData("candidateId", candidateId);
219	    },
220	    []
221	  );
222	
223	  const handleDragOver = useCallback(
224	    (e: React.DragEvent, stage: string) => {
225	      e.preventDefault();
226	      e.dataTransfer.dropEffect = "move";
227	      setDragOverColumn(stage);
228	    },
229	    []
230	  );
231	
232	  const handleDragLeave = useCallback(() => {
233	    setDragOverColumn(null);
234	  }, []);
235	
236	  const handleDrop = useCallback(
237	    (e: React.DragEvent, targetStage: string) => {
238	      e.preventDefault();
239	      setDragOverColumn(null);
240	      const candidateId = e.dataTransfer.getData("candidateId");
241	      if (!candidateId) return;
242	
243	      const candidate = candidates.find((c) => c.id === candidateId);
244	      if (!candidate) return;
245	      if (candidate.stage === targetStage) return;
246	
247	      onStageChange(candidateId, targetStage);
248	      setDraggingId(null);
249	    },
250	    [candidates, onStageChange]
251	  );
252	
253	  // Group candidates by stage
254	  const grouped = stages.reduce<Record<string, KanbanCandidate[]>>(
255	    (acc, stage) => {
256	      acc[stage] = candidates.filter((c) => c.stage === stage);
257	      return acc;
258	    },
259	    {}
260	  );
261	
262	  // Candidates whose stage doesn't match any known column fall into "applied"
263	  const knownStages = new Set(stages);
264	  candidates.forEach((c) => {
265	    if (!knownStages.has(c.stage)) {
266	      grouped["applied"] = [...(grouped["applied"] ?? []), c];
267	    }
268	  });
269	
270	  return (
271	    <div
272	      className="overflow-x-auto pb-4"
273	      onDragEnd={() => {
274	        setDragOverColumn(null);
275	        setDraggingId(null);
276	      }}
277	    >
278	      <div className="flex gap-3 min-w-max">
279	        {stages.map((stage) => (
280	          <KanbanColumn
281	            key={stage}
282	            stage={stage}
283	            candidates={grouped[stage] ?? []}
284	            onDragStart={handleDragStart}
285	            onDragOver={handleDragOver}
286	            onDragLeave={handleDragLeave}
287	            onDrop={handleDrop}
288	            isDragOver={dragOverColumn === stage && draggingId !== null}
289	          />
290	        ))}
291	      </div>
292	    </div>
293	  );
294	}
