27	          activeCandidates: 0,
28	          pendingTasks: 0,
29	          memberCount: 0,
30	          recentActivity: [],
31	          tasksByAssignee: [],
32	        };
33	      }
34	
35	      const [
36	        jobsRes,
37	        pendingTasksRes,
38	        membersRes,
39	        activityRes,
40	        allTasksRes,
41	      ] = await Promise.all([
42	        // Total jobs for this team
43	        (supabase as any)
44	          .from("jobs")
45	          .select("id", { count: "exact", head: true })
46	          .eq("team_id", teamId),
47	
48	        // Pending tasks count
49	        (supabase as any)
50	          .from("tasks")
51	          .select("id", { count: "exact", head: true })
52	          .eq("team_id", teamId)
53	          .neq("status", "done"),
54	
55	        // Team members count
56	        (supabase as any)
57	          .from("team_members")
