59	          .eq("team_id", teamId),
60	
61	        // Last 5 activity items
62	        (supabase as any)
63	          .from("activity_log")
64	          .select("*")
65	          .eq("team_id", teamId)
66	          .order("created_at", { ascending: false })
67	          .limit(5),
68	
69	        // All tasks for assignee summary (limited columns)
70	        (supabase as any)
71	          .from("tasks")
72	          .select("assigned_to, status")
73	          .eq("team_id", teamId)
74	          .not("assigned_to", "is", null),
75	      ]);
76	
77	      // Active candidates: count resumes linked to this team's jobs
78	      // We fetch job IDs first, then count resumes
79	      let activeCandidates = 0;
80	      const { data: jobIds } = await (supabase as any)
81	        .from("jobs")
82	        .select("id")
83	        .eq("team_id", teamId);
84	
85	      if (jobIds && jobIds.length > 0) {
86	        const ids = (jobIds as { id: string }[]).map((j) => j.id);
87	        const { count } = await (supabase as any)
88	          .from("resumes")
