542	// ── Custom Field Input renderer ─────────────────────────────────────────────
543	
544	interface CustomFieldInputProps {
545	  field: JobFormField;
546	  value: string | boolean | string[] | undefined;
547	  onChange: (val: string | boolean | string[]) => void;
548	  error?: string;
549	  disabled: boolean;
550	}
551	
552	function CustomFieldInput({
553	  field,
554	  value,
555	  onChange,
556	  error,
557	  disabled,
558	}: CustomFieldInputProps) {
559	  const fieldId = `custom-${field.id}`;
560	  const strVal = typeof value === "string" ? value : "";
561	  const boolVal = typeof value === "boolean" ? value : false;
562	  const arrVal = Array.isArray(value) ? value : [];
563	
564	  return (
565	    <div className="space-y-1.5">
566	      <Label htmlFor={fieldId}>
567	        {field.label}
568	        {field.required && <span className="text-destructive ml-1">*</span>}
569	      </Label>
570	
571	      {field.field_type === "text" && (
572	        <Input
573	          id={fieldId}
574	          type="text"
575	          placeholder={field.placeholder ?? ""}
576	          value={strVal}
577	          onChange={(e) => onChange(e.target.value)}
578	          aria-invalid={!!error}
579	          disabled={disabled}
580	        />
581	      )}
582	
583	      {field.field_type === "number" && (
584	        <Input
585	          id={fieldId}
586	          type="number"
587	          placeholder={field.placeholder ?? ""}
588	          value={strVal}
589	          onChange={(e) => onChange(e.target.value)}
590	          aria-invalid={!!error}
591	          disabled={disabled}
592	        />
593	      )}
594	
595	      {field.field_type === "url" && (
596	        <Input
597	          id={fieldId}
598	          type="url"
599	          placeholder={field.placeholder ?? "https://"}
600	          value={strVal}
601	          onChange={(e) => onChange(e.target.value)}
602	          aria-invalid={!!error}
603	          disabled={disabled}
604	        />
605	      )}
606	
607	      {field.field_type === "date" && (
608	        <Input
609	          id={fieldId}
610	          type="date"
611	          value={strVal}
612	          onChange={(e) => onChange(e.target.value)}
613	          aria-invalid={!!error}
614	          disabled={disabled}
615	        />
616	      )}
617	
618	      {field.field_type === "textarea" && (
619	        <Textarea
620	          id={fieldId}
621	          placeholder={field.placeholder ?? ""}
622	          value={strVal}
623	          onChange={(e) => onChange(e.target.value)}
624	          aria-invalid={!!error}
625	          disabled={disabled}
626	          rows={4}
627	          className="resize-none"
628	        />
629	      )}
630	
631	      {field.field_type === "checkbox" && (
632	        <div className="flex items-center gap-2">
633	          <Checkbox
634	            id={fieldId}
635	            checked={boolVal}
636	            onCheckedChange={(checked) => onChange(!!checked)}
637	            aria-invalid={!!error}
638	            disabled={disabled}
639	          />
640	          <Label htmlFor={fieldId} className="text-sm font-normal cursor-pointer">
641	            {field.placeholder ?? "Yes"}
642	          </Label>
643	        </div>
644	      )}
645	
646	      {field.field_type === "select" && (
647	        <Select
648	          value={strVal}
649	          onValueChange={onChange}
650	          disabled={disabled}
651	        >
652	          <SelectTrigger id={fieldId} aria-invalid={!!error}>
653	            <SelectValue placeholder={field.placeholder ?? "Select an option"} />
654	          </SelectTrigger>
655	          <SelectContent>
656	            {(field.options ?? []).map((opt) => (
657	              <SelectItem key={opt} value={opt}>
658	                {opt}
659	              </SelectItem>
660	            ))}
661	          </SelectContent>
662	        </Select>
663	      )}
664	
665	      {field.field_type === "multiselect" && (
666	        <div className="space-y-1.5">
667	          {(field.options ?? []).map((opt) => (
668	            <div key={opt} className="flex items-center gap-2">
669	              <Checkbox
670	                id={`${fieldId}-${opt}`}
671	                checked={arrVal.includes(opt)}
672	                onCheckedChange={(checked) => {
673	                  if (checked) {
674	                    onChange([...arrVal, opt]);
675	                  } else {
676	                    onChange(arrVal.filter((v) => v !== opt));
677	                  }
678	                }}
679	                disabled={disabled}
680	              />
681	              <Label
682	                htmlFor={`${fieldId}-${opt}`}
683	                className="text-sm font-normal cursor-pointer"
684	              >
685	                {opt}
686	              </Label>
687	            </div>
688	          ))}
689	        </div>
690	      )}
691	
692	      {error && (
693	        <p className="text-xs text-destructive" role="alert">
694	          {error}
